.confetti-piece.p0{background:#6db7ff;}.confetti-piece.p1{background:#ffb87a;}.confetti-piece.p2{background:#53cf88;}.confetti-piece.p3{background:#d68dff;}.confetti-piece.p4{background:#ffd761;}.confetti-piece.p5{background:#ff8fb6;}
.confetti-piece:nth-child(1){transform:translate(-50%,-50%) rotate(0deg);animation-delay:0.0s;}
.confetti-piece:nth-child(2){transform:translate(-50%,-50%) rotate(20deg);animation-delay:0.03s;}
