.confetti-piece:nth-child(7){transform:translate(-50%,-50%) rotate(120deg);animation-delay:0.0s;}
.confetti-piece:nth-child(8){transform:translate(-50%,-50%) rotate(140deg);animation-delay:0.03s;}
.confetti-piece:nth-child(9){transform:translate(-50%,-50%) rotate(160deg);animation-delay:0.06s;}
.confetti-piece:nth-child(10){transform:translate(-50%,-50%) rotate(180deg);animation-delay:0.09s;}
.confetti-piece:nth-child(11){transform:translate(-50%,-50%) rotate(200deg);animation-delay:0.12s;}
.confetti-piece:nth-child(12){transform:translate(-50%,-50%) rotate(220deg);animation-delay:0.15s;}
.confetti-piece:nth-child(13){transform:translate(-50%,-50%) rotate(240deg);animation-delay:0.0s;}
.confetti-piece:nth-child(14){transform:translate(-50%,-50%) rotate(260deg);animation-delay:0.03s;}
.confetti-piece:nth-child(15){transform:translate(-50%,-50%) rotate(280deg);animation-delay:0.06s;}
.confetti-piece:nth-child(16){transform:translate(-50%,-50%) rotate(300deg);animation-delay:0.09s;}
.confetti-piece:nth-child(17){transform:translate(-50%,-50%) rotate(320deg);animation-delay:0.12s;}
.confetti-piece:nth-child(18){transform:translate(-50%,-50%) rotate(340deg);animation-delay:0.15s;}
@keyframes confettiBurst{0%{opacity:0;transform:translate(-50%,-50%) scale(.4);}15%{opacity:1;}100%{opacity:0;transform:translate(calc(-50% + var(--x,0px)), calc(-50% + var(--y,0px))) rotate(540deg) scale(1);}}
.confetti-piece:nth-child(1){--x:-220px;--y:-120px}.confetti-piece:nth-child(2){--x:-180px;--y:160px}.confetti-piece:nth-child(3){--x:-120px;--y:-180px}.confetti-piece:nth-child(4){--x:-70px;--y:190px}.confetti-piece:nth-child(5){--x:0px;--y:-210px}.confetti-piece:nth-child(6){--x:70px;--y:180px}.confetti-piece:nth-child(7){--x:130px;--y:-180px}.confetti-piece:nth-child(8){--x:190px;--y:150px}.confetti-piece:nth-child(9){--x:240px;--y:-90px}.confetti-piece:nth-child(10){--x:-240px;--y:30px}.confetti-piece:nth-child(11){--x:-140px;--y:120px}.confetti-piece:nth-child(12){--x:120px;--y:110px}.confetti-piece:nth-child(13){--x:220px;--y:60px}.confetti-piece:nth-child(14){--x:-200px;--y:-40px}.confetti-piece:nth-child(15){--x:160px;--y:-130px}.confetti-piece:nth-child(16){--x:-80px;--y:-130px}.confetti-piece:nth-child(17){--x:40px;--y:210px}.confetti-piece:nth-child(18){--x:260px;--y:0px}
