.selection-master-pill,.selection-count-chip,.open-dialer-pill{box-shadow:0 10px 22px rgba(31,42,68,.06);}
.clean-hero{background:linear-gradient(135deg,rgba(255,186,120,.22),rgba(255,255,255,.9),rgba(123,191,255,.20));}
.professional-hero-title{font-size:40px;}
.lux-hero,.compact-color-hero{background:linear-gradient(135deg,rgba(255,186,120,.26),rgba(128,186,255,.22),rgba(110,124,255,.18));color:#17304d;}
