/* chat */
.chat-sidebar-header{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;}
.chat-theme-menu-wrap{position:relative;flex:none;}
.chat-theme-menu-btn{width:42px;height:42px;border:none;border-radius:14px;background:linear-gradient(135deg,rgba(255,255,255,.96),rgba(235,243,255,.95));border:1px solid rgba(95,124,255,.14);box-shadow:0 10px 22px rgba(31,42,68,.08);font-size:24px;line-height:1;color:#274a7a;}
.chat-theme-popover{position:absolute;right:0;top:50px;width:220px;padding:10px;border-radius:18px;background:linear-gradient(180deg,rgba(255,255,255,.98),rgba(240,247,255,.96));border:1px solid rgba(95,124,255,.14);box-shadow:0 24px 56px rgba(13,25,47,.16);z-index:30;}
.chat-theme-popover-title{font-size:12px;font-weight:800;color:#5b6d8b;text-transform:uppercase;letter-spacing:.08em;padding:2px 6px 10px;}
.chat-theme-popover-item{width:100%;display:flex;align-items:center;gap:10px;padding:10px 12px;border:none;border-radius:14px;background:transparent;color:#18314f;font-weight:800;text-align:left;}
.chat-theme-popover-item:hover,.chat-theme-popover-item.active{background:linear-gradient(90deg,rgba(122,189,255,.18),rgba(255,176,120,.12));}
.chat-theme-dot{width:18px;height:18px;border-radius:999px;display:inline-block;box-shadow:inset 0 0 0 1px rgba(255,255,255,.7);}
.chat-theme-dot.whatsapp{background:linear-gradient(135deg,#80d6a4,#4e7bff);}
.chat-theme-dot.hearts{background:linear-gradient(135deg,#7ec9ff,#5874ff);}
.chat-theme-dot.sky{background:linear-gradient(135deg,#9be2ff,#7d9bff);}
.chat-theme-dot.midnight{background:linear-gradient(135deg,#353d79,#2bc2ff);}
.messenger-sidebar,.messenger-main{background:linear-gradient(180deg,rgba(255,255,255,.96),rgba(240,247,255,.95));}
.messenger-window{min-height:55vh;max-height:55vh;background:linear-gradient(180deg,rgba(248,252,255,.98),rgba(233,242,255,.96));border-color:rgba(95,124,255,.12);}
.chat-empty-state{min-height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:#59708f;font-size:14px;}
.chat-empty-state strong{font-size:18px;color:#1b3556;}
.messenger-input-row{padding:4px 2px 0;}
.messenger-input{background:linear-gradient(180deg,rgba(255,255,255,.98),rgba(244,248,255,.97));}
.wa-emoji-picker{background:linear-gradient(180deg,#ffffff,#f3f7ff);border-radius:20px;border:1px solid rgba(95,124,255,.14);}
.wa-emoji-tab{background:#eef3fb;}
.wa-emoji-btn{background:linear-gradient(180deg,#ffffff,#f7fbff);}
/* login */
body.login-body.premium-login-body{background:radial-gradient(circle at 12% 16%,rgba(255,179,102,.18),transparent 24%),radial-gradient(circle at 78% 20%,rgba(114,173,255,.24),transparent 26%),linear-gradient(135deg,#0f1b42,#102550,#0c1838) !important;}
.login-wrap.single-login-wrap::before,.login-wrap::after,.login-wrap.single-login-wrap::after{display:none !important;content:none !important;}
.single-login-wrap.professional-login-grid{max-width:1180px;width:100%;display:grid;grid-template-columns:minmax(390px,480px) minmax(420px,1fr);gap:28px;align-items:stretch;}
.centered-login-card{background:linear-gradient(180deg,rgba(15,25,52,.96),rgba(11,20,42,.98));border:1px solid rgba(124,167,255,.18);box-shadow:0 30px 70px rgba(5,12,32,.34);padding:34px 34px 30px;min-height:560px;}
.centered-login-card .brand-mini,.centered-login-card .muted-copy,.centered-login-card .field label,.centered-login-card .login-premium-line{color:#a9b6d6;}
.centered-login-card h1{font-size:46px;line-height:1.04;color:#fff;}
.centered-login-card .field input{background:linear-gradient(180deg,rgba(8,14,28,.72),rgba(13,21,40,.82));border:1px solid rgba(124,167,255,.16);color:#f4f7ff;}
.centered-login-card .field input::placeholder{color:#8fa3c7;}
.centered-login-card .password-toggle{background:linear-gradient(180deg,rgba(18,32,63,.9),rgba(14,24,47,.95));color:#9cc7ff;border:1px solid rgba(124,167,255,.14);}
.centered-login-card .submit-btn{background:linear-gradient(90deg,#6ab8ff,#4e79ff);box-shadow:0 16px 34px rgba(78,121,255,.34);}
.login-showcase{position:relative;border-radius:34px;padding:28px;background:linear-gradient(135deg,rgba(14,30,66,.95),rgba(20,53,105,.92));border:1px solid rgba(140,178,255,.14);box-shadow:0 28px 72px rgba(6,15,39,.28);overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;min-height:560px;}
.login-showcase::before{content:'';position:absolute;inset:auto -60px -90px auto;width:280px;height:280px;border-radius:50%;background:radial-gradient(circle,rgba(123,187,255,.34),transparent 65%);}
.login-showcase::after{content:'';position:absolute;left:-80px;top:-70px;width:240px;height:240px;border-radius:50%;background:radial-gradient(circle,rgba(255,176,120,.24),transparent 65%);}
.login-showcase-card,.login-showcase-metrics{position:relative;z-index:1;}
.login-showcase-kicker{font-size:12px;font-weight:800;letter-spacing:.14em;color:#b8c8e8;margin-bottom:14px;}
.login-showcase h2{font-size:44px;line-height:1.04;color:#fff;max-width:520px;margin-bottom:14px;}
.login-showcase p{font-size:16px;line-height:1.7;color:#c2d0ea;max-width:560px;}
.login-showcase-tags{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px;}
.login-showcase-tags span{padding:10px 14px;border-radius:999px;border:1px solid rgba(157,188,255,.16);background:rgba(255,255,255,.08);color:#eaf0ff;font-weight:700;font-size:13px;}
.login-showcase-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
.login-showcase-stat{min-height:104px;border-radius:24px;padding:20px;color:#fff;display:flex;flex-direction:column;justify-content:space-between;box-shadow:0 14px 32px rgba(7,15,36,.2);}
.login-showcase-stat strong{font-size:24px;line-height:1.1;}
.login-showcase-stat span{font-size:13px;line-height:1.5;color:rgba(255,255,255,.9);}
.login-showcase-stat.gradient-a{background:linear-gradient(135deg,#ffb469,#ff9468);}
.login-showcase-stat.gradient-b{background:linear-gradient(135deg,#80c5ff,#4f79ff);}
.login-showcase-stat.gradient-c{background:linear-gradient(135deg,#71d7c7,#71aaff);}
.login-showcase-stat.gradient-d{background:linear-gradient(135deg,#9ab9ff,#6f86ff);}
@media (max-width:1100px){.single-login-wrap.professional-login-grid{grid-template-columns:1fr;}.login-showcase{min-height:320px;}.login-showcase h2{font-size:34px;}}
@media (max-width:760px){.centered-login-card{padding:28px 22px;}.centered-login-card h1{font-size:36px;}.login-showcase{padding:22px;}.login-showcase-metrics{grid-template-columns:1fr;}}

/* === V9 login experience refinement === */
body.login-body.premium-login-body.genz-login-shell,
.login-body.premium-login-body.genz-login-shell{
  min-height:100vh;
  margin:0;
  position:relative;
  overflow:hidden;
  background:
    radial-gradient(circle at 12% 18%, rgba(79, 106, 255, 0.35), transparent 24%),
    radial-gradient(circle at 82% 16%, rgba(71, 188, 255, 0.24), transparent 22%),
    radial-gradient(circle at 74% 84%, rgba(86, 118, 255, 0.18), transparent 20%),
    linear-gradient(135deg,#0a1232 0%, #101d4a 48%, #0e1a40 100%) !important;
}
.genz-login-shell .login-floating-orb{
  position:absolute;
  border-radius:999px;
  filter:blur(8px);
  opacity:.7;
  pointer-events:none;
  animation:loginOrbFloat 12s ease-in-out infinite;
}
.genz-login-shell .orb-one{width:260px;height:260px;left:-70px;top:90px;background:radial-gradient(circle,rgba(102,160,255,.48),transparent 70%);}
.genz-login-shell .orb-two{width:300px;height:300px;right:-60px;bottom:70px;background:radial-gradient(circle,rgba(72,203,255,.34),transparent 70%);animation-duration:14s;}
.genz-login-shell .orb-three{width:220px;height:220px;right:24%;top:-80px;background:radial-gradient(circle,rgba(111,124,255,.28),transparent 70%);animation-duration:10s;}

.single-login-wrap.professional-login-grid.genz-login-grid{
  position:relative;
  z-index:2;
  max-width:1180px;
  width:min(1180px, calc(100vw - 42px));
  display:grid;
  grid-template-columns:minmax(410px, 460px) minmax(520px, 1fr);
  gap:26px;
  align-items:stretch;
}
.genz-login-card{
  position:relative;
  border-radius:34px;
  padding:30px 30px 24px;
  min-height:620px;
  background:linear-gradient(180deg,rgba(245,248,255,.98),rgba(233,239,250,.97));
  border:1px solid rgba(167,188,230,.26);
  box-shadow:0 30px 90px rgba(7,18,44,.26);
  color:#163052;
  overflow:hidden;
}
.genz-login-card::before{
  content:"";
  position:absolute;
  inset:0 auto auto 0;
  width:100%;
  height:6px;
  background:linear-gradient(90deg,#7ec7ff,#6d82ff,#80dfd0);
}
.genz-brand-head{
  display:flex;
  align-items:center;
  gap:14px;
  margin-bottom:24px;
}
.genz-brand-head .login-logo-main{
  width:146px;
  max-width:146px;
  height:auto;
  object-fit:contain;
  filter:none !important;
  transform:none !important;
}
.login-brand-copy{display:flex;flex-direction:column;gap:4px;}
.brand-mini-strong{
  font-size:12px;
  font-weight:900;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:#5f7091 !important;
}
.genz-login-card .login-premium-line{
  color:#496284 !important;
  font-size:13px;
  line-height:1.5;
}
.login-copy-stack{display:flex;flex-direction:column;gap:10px;margin-bottom:22px;}
.login-kicker{
  display:inline-flex;
  align-items:center;
  align-self:flex-start;
  padding:8px 12px;
  border-radius:999px;
  background:linear-gradient(90deg,rgba(122,195,255,.16),rgba(110,124,255,.12));
  border:1px solid rgba(106,139,227,.16);
  color:#466384;
  font-size:12px;
  font-weight:800;
  letter-spacing:.02em;
}
.genz-login-card h1{
  font-size:48px;
  line-height:1.03;
  letter-spacing:-0.04em;
  color:#102846;
  margin:0;
}
.genz-login-card .muted-copy{
  color:#5d718f !important;
  font-size:15px;
  line-height:1.72;
  margin:0;
}
.login-form-advanced{display:flex;flex-direction:column;gap:18px;margin-top:8px;}
.genz-login-card .field label{
  color:#576b8b !important;
  font-weight:800;
  font-size:12px;
  letter-spacing:.04em;
  text-transform:uppercase;
  margin-bottom:9px;
}
.genz-login-card .field input{
  min-height:58px;
  padding:0 18px;
  border-radius:18px;
  background:linear-gradient(180deg,#ffffff,#f1f6ff);
  border:1px solid rgba(124,154,218,.26);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.85), 0 8px 20px rgba(76,105,168,.08);
  color:#15314f;
  font-size:17px;
  font-weight:700;
}
.genz-login-card .field input::placeholder{color:#8a9dbd;}
.genz-login-card .field input:focus{
  outline:none;
  border-color:rgba(84,132,255,.58);
  box-shadow:0 0 0 4px rgba(95,124,255,.14), inset 0 1px 0 rgba(255,255,255,.85);
}
.genz-login-card .password-wrap{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;}
.genz-login-card .password-toggle{
  min-width:92px;
  border-radius:18px;
  border:1px solid rgba(95,124,255,.16);
  background:linear-gradient(135deg,#13305a,#224780);
  color:#eef5ff;
  font-weight:800;
  font-size:15px;
  box-shadow:0 14px 24px rgba(16,42,83,.18);
}
.genz-login-card .password-toggle:hover{transform:translateY(-1px);}
.login-launch-btn{
  min-height:62px;
  border:none;
  border-radius:20px;
  font-size:18px;
  font-weight:900;
  letter-spacing:.02em;
  color:#fff;
  background:linear-gradient(90deg,#79c8ff 0%, #5586ff 48%, #5173ff 100%) !important;
  box-shadow:0 20px 36px rgba(73,113,255,.30);
}
.login-launch-btn:hover{transform:translateY(-1px);}
.login-footnote{
  margin-top:auto;
  padding-top:18px;
  color:#617392;
  font-size:12px;
  font-weight:700;
  letter-spacing:.02em;
}
.genz-login-showcase{
  position:relative;
  min-height:620px;
  border-radius:36px;
  overflow:hidden;
  padding:34px;
  background:
    radial-gradient(circle at 80% 16%, rgba(83,200,255,.18), transparent 18%),
    radial-gradient(circle at 18% 82%, rgba(122,133,255,.18), transparent 20%),
    linear-gradient(145deg, rgba(12,29,67,.96), rgba(18,47,99,.96));
  border:1px solid rgba(143,181,255,.16);
  box-shadow:0 32px 92px rgba(6,16,42,.28);
  display:flex;
  flex-direction:column;
  justify-content:space-between;
}
.genz-login-showcase::before,
.genz-login-showcase::after{
  content:"";
  position:absolute;
  inset:auto;
  pointer-events:none;
}
.genz-login-showcase::before{
  width:340px;
  height:340px;
  right:-110px;
  bottom:-120px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(114,173,255,.28),transparent 66%);
}
.genz-login-showcase::after{
  width:220px;
  height:220px;
  left:-50px;
  top:-50px;
  border-radius:50%;
  background:radial-gradient(circle,rgba(255,182,120,.16),transparent 68%);
}
.login-showcase-top,
.login-wave-panel,
.genz-preview-grid{position:relative;z-index:1;}
.genz-login-showcase .login-showcase-kicker{
  color:#9cc8ff;
  font-size:13px;
  font-weight:900;
  letter-spacing:.16em;
  margin-bottom:16px;
}
.genz-login-showcase h2{
  margin:0;
  color:#ffffff;
  font-size:50px;
  line-height:1.02;
  letter-spacing:-0.04em;
  max-width:620px;
}
.genz-login-showcase p{
  margin:16px 0 0;
  color:#c2d7f7;
  font-size:16px;
  line-height:1.75;
  max-width:580px;
}
.login-wave-panel{
  margin:26px 0 24px;
  min-height:190px;
  border-radius:30px;
  padding:22px;
  background:linear-gradient(160deg,rgba(255,255,255,.06),rgba(255,255,255,.03));
  border:1px solid rgba(143,181,255,.14);
  overflow:hidden;
}
.login-wave,
.login-wave-glow{
  position:absolute;
  left:50%;
  top:50%;
  transform:translate(-50%,-50%);
  border-radius:999px;
  pointer-events:none;
}
.login-wave-a{
  width:74%;
  height:96px;
  background:radial-gradient(circle at 20% 50%, rgba(155,93,255,.95), transparent 54%), radial-gradient(circle at 78% 50%, rgba(40,185,255,.82), transparent 48%);
  filter:blur(16px);
  animation:loginWaveOne 7s ease-in-out infinite;
}
.login-wave-b{
  width:58%;
  height:58px;
  background:linear-gradient(90deg,rgba(73,109,255,.10),rgba(170,88,255,.66),rgba(36,190,255,.74));
  filter:blur(8px);
  animation:loginWaveTwo 9s ease-in-out infinite;
}
.login-wave-glow{
  width:68%;
  height:120px;
  background:radial-gradient(circle,rgba(102,160,255,.18),transparent 62%);
}
.login-wave-content{
  position:relative;
  z-index:1;
  display:flex;
  align-items:center;
  gap:14px;
  padding:12px 14px;
  border-radius:20px;
  background:linear-gradient(135deg,rgba(255,255,255,.12),rgba(255,255,255,.05));
  width:max-content;
  max-width:100%;
  color:#fff;
}
.login-wave-logo{width:44px;height:44px;object-fit:contain;filter:none !important;}
.login-wave-content strong{display:block;font-size:18px;line-height:1.1;}
.login-wave-content span{display:block;color:#c8d8f4;font-size:12px;line-height:1.5;}
.genz-preview-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
.genz-preview-grid .login-showcase-stat{
  min-height:118px;
  padding:18px 18px 16px;
  border-radius:24px;
  display:flex;
  flex-direction:column;
  gap:12px;
  justify-content:space-between;
  color:#fff;
  box-shadow:0 18px 36px rgba(4,15,38,.18);
}
.genz-preview-grid .login-showcase-stat strong{font-size:22px;line-height:1.08;}
.genz-preview-grid .login-showcase-stat em{font-style:normal;font-size:30px;font-weight:900;line-height:1;color:#fff;}
.genz-preview-grid .login-showcase-stat span{font-size:13px;line-height:1.5;color:rgba(255,255,255,.9);}
.genz-preview-grid .gradient-a{background:linear-gradient(135deg,#ffb26d,#ff8f72);}
.genz-preview-grid .gradient-b{background:linear-gradient(135deg,#82ceff,#5c7dff);}
.genz-preview-grid .gradient-c{background:linear-gradient(135deg,#7cdacb,#69a8ff);}
.genz-preview-grid .gradient-d{background:linear-gradient(135deg,#9ab7ff,#6e7fff);}

.login-success-overlay{
  position:fixed;
  inset:0;
  display:grid;
  place-items:center;
  opacity:0;
  pointer-events:none;
  z-index:100;
}
.login-success-overlay.active{opacity:1;pointer-events:auto;}
.login-success-backdrop{
  position:absolute;
  inset:0;
  background:radial-gradient(circle at 50% 30%, rgba(91,124,255,.22), transparent 28%), linear-gradient(135deg, rgba(10,18,50,.84), rgba(12,22,58,.96));
  backdrop-filter:blur(12px);
  animation:loginSuccessBackdrop .65s ease forwards;
}
.login-success-content{
  position:relative;
  z-index:1;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:18px;
  color:#fff;
  animation:loginSuccessContent 1.1s cubic-bezier(.2,.8,.2,1) forwards;
}
.login-success-logo-ring{
  width:138px;
  height:138px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:radial-gradient(circle at 30% 30%, rgba(255,255,255,.22), rgba(255,255,255,.06) 60%, rgba(255,255,255,.02) 100%);
  border:1px solid rgba(160,194,255,.24);
  box-shadow:0 0 0 14px rgba(114,173,255,.08), 0 0 0 30px rgba(114,173,255,.04), 0 24px 60px rgba(10,20,56,.34);
}
.login-success-logo{width:68px;height:68px;object-fit:contain;filter:none !important;animation:loginLogoPulse 1.25s ease-in-out infinite;}
.login-success-text{font-size:42px;font-weight:900;letter-spacing:-0.04em;text-align:center;}
.login-success-subtext{font-size:15px;color:#c9d7f4;text-align:center;}
.login-success-active .genz-login-grid{animation:loginGridFadeOut .55s ease forwards;}

@keyframes loginOrbFloat{
  0%,100%{transform:translate3d(0,0,0) scale(1);}
  50%{transform:translate3d(0,-16px,0) scale(1.06);}
}
@keyframes loginWaveOne{
  0%,100%{transform:translate(-50%,-50%) rotate(-6deg) scaleX(1);}
  50%{transform:translate(-50%,-50%) rotate(6deg) scaleX(1.08);}
}
@keyframes loginWaveTwo{
  0%,100%{transform:translate(-50%,-50%) rotate(8deg) scaleX(1);}
  50%{transform:translate(-50%,-50%) rotate(-8deg) scaleX(1.12);}
}
@keyframes loginGridFadeOut{
  from{opacity:1;transform:scale(1);filter:blur(0);}
  to{opacity:0;transform:scale(.96);filter:blur(10px);}
}
@keyframes loginSuccessBackdrop{
  from{opacity:0;}
  to{opacity:1;}
}
@keyframes loginSuccessContent{
  0%{opacity:0;transform:scale(.72) translateY(18px);}
  55%{opacity:1;transform:scale(1.08) translateY(0);}
