.candidate-form-grid > [data-sort-no],
.candidate-compact-grid > [data-sort-no]{position:relative;transition:transform .16s ease, box-shadow .16s ease, background .16s ease;}
.candidate-form-grid > [data-sort-no]::before,
.candidate-compact-grid > [data-sort-no]::before{
  content:attr(data-sort-no);
  position:absolute;
  top:11px;
  left:2px;
  display:block;
  background:transparent;
  color:#8aa0c1;
  font-size:11px;
  font-weight:800;
  letter-spacing:.02em;
  line-height:1;
  box-shadow:none;
  z-index:2;
