.candidate-compact-grid > [data-sort-no][draggable="true"]{cursor:grab;}
.candidate-form-grid > [data-sort-no][data-dragging="true"],
.candidate-compact-grid > [data-sort-no][data-dragging="true"]{opacity:.58;transform:scale(.985);}
.candidate-form-grid > [data-sort-no]:hover,
.candidate-compact-grid > [data-sort-no]:hover{transform:translateY(-1px);}
.candidate-form-grid > [data-sort-no] .field,
.candidate-compact-grid > [data-sort-no] .field{padding-top:0;}
.candidate-form-grid > [data-sort-no] > .field,
.candidate-compact-grid > [data-sort-no] > .field,
.candidate-form-grid > [data-sort-no].field,
.candidate-compact-grid > [data-sort-no].field{position:relative;}
.candidate-form-grid > [data-sort-no] > .field label,
.candidate-compact-grid > [data-sort-no] > .field label,
