/* Login redesign */
.login-body.login-spectrum-shell{
  position:relative;
  min-height:100vh;
  overflow:hidden !important;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:30px 26px !important;
  background:
    radial-gradient(circle at 12% 14%,rgba(26,111,255,.20),transparent 24%),
    radial-gradient(circle at 84% 18%,rgba(255,175,58,.18),transparent 24%),
    radial-gradient(circle at 70% 78%,rgba(29,201,255,.18),transparent 24%),
    linear-gradient(135deg,#061127 0%,#0a1735 38%,#0f2555 100%) !important;
}
.login-spectrum-backdrop,
.login-spectrum-stage{position:relative;z-index:1;width:100%;}
.login-spectrum-backdrop{position:absolute;inset:0;overflow:hidden;pointer-events:none;}
.login-spectrum-grid,
.login-spectrum-noise,
.login-spectrum-orb,
.login-spectrum-beam{position:absolute;pointer-events:none;}
.login-spectrum-grid{
  inset:-8%;
  background:
    linear-gradient(rgba(98,138,255,.09) 1px,transparent 1px),
    linear-gradient(90deg,rgba(98,138,255,.09) 1px,transparent 1px);
  background-size:58px 58px;
  mask-image:radial-gradient(circle at center,rgba(0,0,0,.92),transparent 82%);
  transform:perspective(1000px) rotateX(72deg) scale(1.4);
  transform-origin:bottom center;
  opacity:.44;
}
.login-spectrum-noise{
  inset:0;
  opacity:.06;
  background-image:radial-gradient(rgba(255,255,255,.8) .8px,transparent .8px);
  background-size:18px 18px;
}
.login-spectrum-orb{
  border-radius:50%;
  filter:blur(18px);
  animation:v14Float 9s ease-in-out infinite;
}
.login-spectrum-orb-a{left:-90px;top:12%;width:260px;height:260px;background:radial-gradient(circle,rgba(26,111,255,.58),rgba(26,111,255,0));}
.login-spectrum-orb-b{right:4%;top:10%;width:220px;height:220px;background:radial-gradient(circle,rgba(255,170,56,.52),rgba(255,170,56,0));animation-delay:-2.5s;}
.login-spectrum-orb-c{right:18%;bottom:-50px;width:260px;height:260px;background:radial-gradient(circle,rgba(29,201,255,.38),rgba(29,201,255,0));animation-delay:-4.2s;}
.login-spectrum-beam{
  width:42vw;
  height:2px;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.5),transparent);
  opacity:.38;
  filter:blur(.4px);
}
.login-spectrum-beam-a{top:22%;left:8%;transform:rotate(-16deg);animation:v14Beam 8s linear infinite;}
.login-spectrum-beam-b{bottom:20%;right:6%;transform:rotate(14deg);animation:v14Beam 8.8s linear infinite reverse;}

.login-spectrum-stage{
  display:grid;
  grid-template-columns:minmax(0,1.15fr) minmax(380px,.85fr);
  align-items:center;
  gap:34px;
  max-width:1280px;
  margin:0 auto;
}
.login-spectrum-showcase,
.login-spectrum-card-shell{position:relative;}
.login-spectrum-showcase{
  padding:18px 8px 18px 8px;
}
.login-spectrum-badge{
  display:inline-flex;
  align-items:center;
  gap:8px;
  min-height:36px;
  padding:0 16px;
  border-radius:999px;
  color:#dbe8ff;
  font-size:12px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  border:1px solid rgba(123,159,255,.28);
  background:linear-gradient(135deg,rgba(255,255,255,.08),rgba(255,255,255,.02));
  box-shadow:0 16px 28px rgba(0,0,0,.16);
}
.login-spectrum-logo{
  display:block;
  width:min(560px,100%);
  max-width:100%;
  margin:20px 0 24px;
  filter:drop-shadow(0 24px 38px rgba(4,13,34,.28));
}
.login-spectrum-showcase h1{
  margin:0;
  font-size:clamp(36px,4vw,62px);
  line-height:.98;
  letter-spacing:-.05em;
  color:#f7fbff;
  max-width:720px;
}
.login-spectrum-showcase p{
  margin:16px 0 0;
  max-width:660px;
  color:#9fb7dd;
  font-size:16px;
  line-height:1.75;
}
.login-signal-grid,
.login-panel-grid{
  display:grid;
  gap:14px;
  margin-top:24px;
}
.login-signal-grid{grid-template-columns:repeat(3,minmax(0,1fr));}
.login-panel-grid{grid-template-columns:repeat(3,minmax(0,1fr));}
.login-signal-card,
.login-panel-card{
  position:relative;
  overflow:hidden;
  padding:18px 18px 16px;
  border-radius:24px;
  border:1px solid rgba(255,255,255,.12);
  background:linear-gradient(180deg,rgba(11,25,57,.82),rgba(8,18,42,.74));
  box-shadow:0 20px 46px rgba(3,10,27,.26), inset 0 1px 0 rgba(255,255,255,.07);
  backdrop-filter:blur(10px);
}
.login-signal-card::after,
.login-panel-card::after{
  content:"";
  position:absolute;
  inset:auto -10% -30px -10%;
  height:76px;
  background:radial-gradient(circle at 50% 0,rgba(255,255,255,.16),transparent 72%);
}
.login-signal-card span,
.login-panel-card span{
  display:block;
  color:#7fd7ff;
  font-size:11px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.login-signal-card strong,
.login-panel-card strong{
  display:block;
  margin-top:10px;
  color:#f2f7ff;
  font-size:15px;
  line-height:1.5;
  font-weight:700;
}
.login-panel-card-2 span{color:#ffcb70;}
.login-panel-card-3 span{color:#95f2be;}

.login-spectrum-card-shell{
  isolation:isolate;
}
.login-spectrum-card-edge{
  position:absolute;
  inset:-1px;
  border-radius:34px;
  background:linear-gradient(135deg,rgba(29,111,255,.92),rgba(29,201,255,.62),rgba(255,176,40,.75),rgba(255,109,61,.82));
  filter:blur(18px);
  opacity:.28;
}
.login-spectrum-card{
  position:relative;
  z-index:1;
  padding:30px;
  border-radius:32px;
  background:linear-gradient(180deg,rgba(9,20,46,.94),rgba(7,16,36,.90));
  border:1px solid rgba(122,161,255,.18);
  box-shadow:0 32px 70px rgba(3,11,29,.34), inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter:blur(16px);
}
.login-card-topline{
  display:inline-flex;
  align-items:center;
  gap:10px;
  min-height:34px;
  padding:0 14px;
  border-radius:999px;
  background:linear-gradient(135deg,rgba(255,255,255,.08),rgba(255,255,255,.03));
  border:1px solid rgba(122,161,255,.14);
  color:#cbdcff;
  font-size:12px;
  font-weight:700;
}
.login-card-status-dot{
  width:10px;
  height:10px;
  border-radius:50%;
  background:linear-gradient(135deg,#1dc9ff,#8ff2ff);
  box-shadow:0 0 0 6px rgba(29,201,255,.14);
}
.login-card-copy{margin-top:22px;}
.login-card-copy h2{
  margin:0;
  color:#fff;
  font-size:42px;
  line-height:1;
  letter-spacing:-.04em;
}
.login-card-copy p{
  margin:12px 0 0;
  color:#96acd0;
  line-height:1.7;
}
.login-spectrum-form{display:grid;gap:18px;margin-top:26px;}
.login-field-block{display:grid;gap:10px;}
.login-field-block > span{
  color:#d7e3f8;
  font-size:12px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.login-field-shell{
  display:flex;
  align-items:center;
  min-height:58px;
  padding:0 12px 0 16px;
  border-radius:18px;
  background:linear-gradient(180deg,rgba(10,24,54,.94),rgba(7,18,40,.92));
  border:1px solid rgba(118,153,225,.18);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.03),0 16px 28px rgba(0,0,0,.18);
}
.login-field-shell:focus-within{
  border-color:rgba(71,165,255,.58);
  box-shadow:0 0 0 4px rgba(34,120,255,.14),0 20px 34px rgba(0,0,0,.22);
}
.login-field-shell input{
  flex:1;
  border:none;
  outline:none;
  background:transparent;
  color:#edf4ff;
  font:inherit;
  min-width:0;
}
.login-field-shell input::placeholder{color:#7289b0;}
.login-password-toggle{
  flex:none;
  min-width:82px;
  height:42px;
  border:none;
  border-radius:14px;
  color:#fff;
  font-size:13px;
  font-weight:800;
  background:linear-gradient(135deg,#0f61eb 0%,#1d95ff 58%,#6ad4ff 100%);
  box-shadow:0 12px 24px rgba(18,34,68,.22), inset 0 1px 0 rgba(255,255,255,.2);
}
.login-card-meta{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  flex-wrap:wrap;
}
.login-card-meta-text{color:#7f98bf;font-size:12px;}
.login-remember-line{
  display:inline-flex;
  align-items:center;
  gap:8px;
  color:#dbe7fb;
  font-size:13px;
}
.login-remember-line input{accent-color:#1dc9ff;}
.login-spectrum-submit{
  position:relative;
  overflow:hidden;
  min-height:58px;
  border:none;
  border-radius:18px;
  color:#fff;
  font-size:16px;
  font-weight:900;
  letter-spacing:.01em;
  background:linear-gradient(135deg,#ffb028 0%,#ff7d34 44%,#ff5f44 100%);
  box-shadow:0 24px 42px rgba(255,108,61,.24), inset 0 1px 0 rgba(255,255,255,.24);
}
.login-spectrum-submit::after{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(120deg,transparent 0%,rgba(255,255,255,.22) 46%,transparent 56%);
  transform:translateX(-160%);
  animation:v14Sweep 3.4s ease-in-out infinite;
}
.login-spectrum-submit span{position:relative;z-index:1;}
.login-spectrum-submit:disabled,
.login-password-toggle:disabled{opacity:.82;cursor:not-allowed;}
.login-spectrum-success .login-success-text{color:#fff;}
.login-spectrum-success .login-success-subtext{color:#c9d8f6;}
.login-spectrum-success-ring{
  background:linear-gradient(135deg,#0f61eb,#18b8ff,#ffb028,#ff6d3d) !important;
}

@keyframes v14Float{
  0%,100%{transform:translate3d(0,0,0) scale(1);}
  50%{transform:translate3d(0,-20px,0) scale(1.04);}
}
@keyframes v14Beam{
  0%{opacity:.12;transform:translateX(-6%) scaleX(.96) rotate(var(--beam-angle,0deg));}
  50%{opacity:.4;}
  100%{opacity:.12;transform:translateX(6%) scaleX(1.04) rotate(var(--beam-angle,0deg));}
}
@keyframes v14Sweep{
  0%{transform:translateX(-160%);} 40%{transform:translateX(-160%);} 100%{transform:translateX(160%);} }

@media (max-width:1180px){
  .login-spectrum-stage{grid-template-columns:1fr;gap:24px;max-width:760px;}
  .login-spectrum-showcase{padding:0;}
  .login-signal-grid,.login-panel-grid{grid-template-columns:repeat(2,minmax(0,1fr));}
}
@media (max-width:720px){
  .login-body.login-spectrum-shell{padding:16px !important;}
  .login-spectrum-card{padding:24px 18px;}
  .login-card-copy h2{font-size:34px;}
  .login-spectrum-showcase h1{font-size:34px;}
  .login-spectrum-showcase p{font-size:14px;line-height:1.65;}
  .login-signal-grid,.login-panel-grid{grid-template-columns:1fr;}
  .login-card-meta{align-items:flex-start;}
}

