.cc-subtle-orb-c{width:260px;height:260px;left:46%;bottom:-100px;background:radial-gradient(circle,rgba(255,255,255,.36),rgba(255,255,255,0));animation-delay:-4.1s;}
.cc-subtle-login-stage{min-height:100vh;display:grid;place-items:center;padding:28px;}
.cc-subtle-login-card{position:relative;display:grid;grid-template-columns:minmax(340px,1.05fr) minmax(340px,.95fr);width:min(1120px,100%);min-height:620px;border-radius:34px;overflow:hidden;background:rgba(255,255,255,.08);box-shadow:0 36px 90px rgba(28,20,59,.28);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.3);animation:ccLoginCardEnter .75s cubic-bezier(.22,.9,.24,1);}
.cc-subtle-brand-panel{position:relative;padding:42px 42px 38px 48px;display:flex;flex-direction:column;justify-content:center;gap:18px;background:linear-gradient(135deg,rgba(255,170,92,.9) 0%,rgba(255,145,114,.88) 48%,rgba(255,131,142,.78) 100%);}
.cc-subtle-brand-glow{position:absolute;inset:18px 22px auto auto;width:220px;height:220px;border-radius:999px;background:radial-gradient(circle,rgba(255,255,255,.28),rgba(255,255,255,0));filter:blur(10px);}
