.cc-subtle-divider-wave{position:absolute;top:0;right:-2px;width:124px;height:100%;background:#fff;border-radius:44px 0 0 44px;clip-path:path('M 92 0 C 34 80, 128 150, 74 230 C 28 300, 122 382, 64 476 C 28 540, 76 588, 88 620 L 124 620 L 124 0 Z');opacity:.98;box-shadow:-10px 0 28px rgba(255,255,255,.15);}
.cc-subtle-form-panel{position:relative;padding:44px 44px 40px 74px;background:linear-gradient(180deg,rgba(255,255,255,.97),rgba(248,249,255,.96));display:flex;align-items:center;justify-content:center;}
