.cc-subtle-submit{position:relative;height:54px;border:none;border-radius:16px;cursor:pointer;color:#fff;font-size:15px;font-weight:900;background:linear-gradient(135deg,#ffb04d 0%,#ff8f72 46%,#f95a84 100%);box-shadow:0 18px 36px rgba(255,123,105,.24);overflow:hidden;transition:transform .18s ease,box-shadow .18s ease,opacity .18s ease;}
.cc-subtle-submit::before{content:'';position:absolute;inset:-30% auto -30% -40%;width:42%;background:linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,.32),rgba(255,255,255,0));transform:skewX(-22deg);animation:ccButtonSweep 3.8s linear infinite;}
.cc-subtle-submit span{position:relative;z-index:1;}
.cc-subtle-submit:hover{transform:translateY(-1px);box-shadow:0 20px 38px rgba(255,123,105,.28);}
.cc-subtle-submit:disabled{cursor:not-allowed;opacity:.8;}
.cc-subtle-error{padding:12px 14px;border-radius:14px;background:#fff0f0;color:#c43c45;border:1px solid #ffd2d7;font-weight:700;font-size:13px;}
.cc-subtle-success .login-success-text{color:#fff;}
.cc-subtle-success .login-success-subtext{color:#d8e2fb;}
.cc-subtle-success-ring{background:linear-gradient(135deg,#ffb04d,#f95a84,#4ca6ff) !important;box-shadow:0 0 0 10px rgba(255,255,255,.08),0 18px 42px rgba(15,18,52,.35) !important;}

@keyframes ccLoginCardEnter{0%{opacity:0;transform:translateY(24px) scale(.98);}100%{opacity:1;transform:translateY(0) scale(1);}}
@keyframes ccSubtleFloat{0%,100%{transform:translateY(0) scale(1);}50%{transform:translateY(-18px) scale(1.04);}}
