/* ===== Pipeline Hub P25 Upgrade ===== */
.pipeline-income-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.revenue-target-edit-trigger {
  min-width: 132px;
}
.revenue-target-edit-trigger.active {
  background: linear-gradient(135deg, #4074ff, #5b87ff);
  color: #fff;
  border-color: transparent;
}
.pipeline-target-editor {
  width: 100%;
  display: flex;
  align-items: flex-end;
  gap: 12px;
  flex-wrap: wrap;
}
.pipeline-target-editor-field {
  min-width: 220px;
  flex: 1 1 240px;
}
.pipeline-target-editor-field span {
  display: block;
  margin-bottom: 6px;
}
.pipeline-income-sticky {
  position: relative;
  top: auto;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 16px;
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(64,116,255,0.13), rgba(47,205,165,0.13));
  border: 1px solid rgba(64,116,255,0.18);
  box-shadow: 0 10px 24px rgba(36, 63, 134, 0.06);
}
.pipeline-income-metrics {
  display: flex;
  align-items: stretch;
  gap: 10px;
  flex-wrap: wrap;
}
.pipeline-income-block {
  min-width: 138px;
  padding: 8px 12px;
  border-radius: 14px;
  background: rgba(255,255,255,0.78);
  border: 1px solid rgba(84, 127, 255, 0.15);
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pipeline-income-block span {
  font-size: 10px;
  font-weight: 800;
  color: #5f6d8b;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.pipeline-income-block strong {
  font-size: 18px;
  color: #16315e;
}
.pipeline-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.pipeline-summary-card{min-height:88px;}
.pipeline-summary-card.summary-indigo{background:linear-gradient(135deg,#416dff,#5f7eff,#8b5cff);}
.pipeline-summary-card.summary-sky{background:linear-gradient(135deg,#2f8cff,#43b8ff,#66d0ff);}
.pipeline-summary-card.summary-violet{background:linear-gradient(135deg,#7a62ff,#9a67ff,#c07bff);}
.pipeline-summary-card.summary-emerald{background:linear-gradient(135deg,#0fa77f,#38c98b,#6fd27a);}
.compact-middle-income-card .table-title{font-size:18px;}
.compact-middle-income-card .helper-text{font-size:12px;line-height:1.45;}
.compact-lower-grid .revenue-journey-card{min-height:86px;}
.pipeline-view-switches,
.pipeline-leaderboard-switches {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.pipeline-view-switches .ghost-btn.active,
.pipeline-leaderboard-switches .ghost-btn.active {
  background: linear-gradient(135deg, #4074ff, #5b87ff);
  color: #fff;
  border-color: transparent;
}
.pipeline-insight-list {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.pipeline-insight-chip {
  display: inline-flex;
  align-items: center;
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(80, 118, 255, 0.12);
  color: #28416f;
  font-size: 12px;
  font-weight: 700;
}
.pipeline-modal-backdrop {
  align-items: flex-start;
  overflow: auto;
  padding: 8px;
}
.pipeline-upgrade-modal {
  width: min(1820px, calc(100vw - 12px));
  max-height: calc(100vh - 10px);
  overflow: auto;
  padding: 26px 28px 20px;
  border-radius: 32px;
  margin: 2px auto;
}
.pipeline-add-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.85fr) minmax(360px, 0.78fr);
  gap: 24px;
  align-items: start;
}
.pipeline-main-form,
.pipeline-wa-panel {
  padding: 20px;
  border-radius: 24px;
  background: linear-gradient(180deg, rgba(255,255,255,0.95), rgba(243,248,255,0.94));
  border: 1px solid rgba(102, 129, 199, 0.18);
  box-shadow: 0 16px 34px rgba(28, 54, 108, 0.08);
}
.pipeline-wa-panel {
  min-width: 0;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
}
.pipeline-autofill-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(222, 249, 238, 0.96), rgba(233, 243, 255, 0.96));
  border: 1px solid rgba(47, 205, 165, 0.22);
  color: #1e5c4d;
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 0;
}
.pipeline-autofill-copy {
  min-width: 0;
}
.pipeline-autofill-banner strong {
  display: block;
  font-size: 15px;
  color: #183454;
}
.pipeline-autofill-banner .helper-text {
  margin-top: 2px;
  white-space: normal;
}
.pipeline-auto-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(185px, 1fr));
  gap: 18px;
}
.pipeline-form-field {
  margin: 0;
  min-width: 0;
  padding: 14px 14px 16px !important;
  border-radius: 18px !important;
  box-shadow: 0 10px 22px rgba(31, 55, 109, 0.06) !important;
}
.pipeline-auto-grid > .pipeline-form-field:nth-child(4n + 1) {
  background: linear-gradient(180deg, rgba(244, 249, 255, 0.98), rgba(235, 244, 255, 0.95)) !important;
}
.pipeline-auto-grid > .pipeline-form-field:nth-child(4n + 2) {
  background: linear-gradient(180deg, rgba(245, 255, 248, 0.98), rgba(233, 249, 240, 0.95)) !important;
}
.pipeline-auto-grid > .pipeline-form-field:nth-child(4n + 3) {
  background: linear-gradient(180deg, rgba(255, 247, 251, 0.98), rgba(251, 238, 247, 0.95)) !important;
}
.pipeline-auto-grid > .pipeline-form-field:nth-child(4n + 4) {
  background: linear-gradient(180deg, rgba(255, 250, 243, 0.98), rgba(250, 242, 231, 0.95)) !important;
}
.pipeline-form-field > span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: center;
  text-align: center;
  margin: 0 auto 8px;
  padding: 4px 10px;
  min-height: 24px;
  border-radius: 999px;
  background: rgba(255,255,255,0.92);
  border: 1px solid rgba(111, 138, 205, 0.18);
  color: #39557e;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.02em;
  line-height: 1.1;
}
.pipeline-form-field input,
.pipeline-form-field select,
.pipeline-form-field textarea,
.pipeline-wa-panel input,
.pipeline-wa-panel select {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 12px 14px !important;
}
.pipeline-inline-field-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
}
.pipeline-inline-picker-row {
  grid-template-columns: minmax(0, 1fr) 46px;
}
.pipeline-choice-field select {
  min-width: 0;
}
.pipeline-inline-add-btn {
  width: 46px;
  min-width: 46px;
  min-height: 46px !important;
  padding: 0 !important;
  border-radius: 14px !important;
  font-size: 24px !important;
  font-weight: 900 !important;
  line-height: 1 !important;
}
.pipeline-inline-add-btn:hover {
  transform: translateY(-1px);
}
.pipeline-inline-field-row .ghost-btn {
  min-height: 42px;
  white-space: nowrap;
  padding-inline: 12px;
}
.pipeline-file-box .helper-text {
  min-height: 34px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.pipeline-file-box input[type="file"] {
  margin-top: 6px;
  font-size: 12px;
}
.pipeline-wa-number-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}
.pipeline-message-preview {
  min-height: 176px;
  max-height: 240px;
  overflow: auto;
  padding: 14px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(47,205,165,0.08), rgba(64,116,255,0.06));
  border: 1px solid rgba(47,205,165,0.18);
  color: #243757;
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
}
.pipeline-attach-check {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #35517d;
}
.full-width-btn {
  width: 100%;
}
.compact-results {
  max-height: 320px;
}
.extra-grid {
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 14px;
}
.pipeline-extra-grid .field,
.pipeline-notes-field {
  margin-bottom: 0;
}
.pipeline-notes-field textarea {
  min-height: 90px;
}
.pipeline-modal-footer {
  position: sticky;
  bottom: -8px;
  z-index: 2;
  margin-top: 14px;
  padding-top: 12px;
  padding-bottom: 2px;
  background: linear-gradient(180deg, rgba(247, 250, 255, 0), rgba(247, 250, 255, 0.92) 22%, rgba(247, 250, 255, 0.98) 100%);
}
@media (max-width: 1260px) {
  .pipeline-add-layout {
    grid-template-columns: minmax(0, 1.28fr) minmax(300px, 0.9fr);
  }
  .pipeline-auto-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 1080px) {
  .pipeline-add-layout,
  .pipeline-summary-grid,
  .extra-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .pipeline-wa-panel {
    grid-column: 1 / -1;
  }
  .pipeline-auto-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .pipeline-income-sticky {
    flex-direction: column;
    align-items: flex-start;
  }
}
@media (max-width: 760px) {
  .pipeline-add-layout,
  .pipeline-summary-grid,
  .pipeline-auto-grid,
  .extra-grid {
    grid-template-columns: 1fr;
  }
  .pipeline-upgrade-modal {
    width: min(98vw, 98vw);
    max-height: calc(100vh - 16px);
    padding: 14px 14px 12px;
  }
  .pipeline-autofill-banner {
    flex-direction: column;
    align-items: flex-start;
  }
}

