  --muted:#586f98;
  --line:#d8e2f0;
  --grad-1-a:#ffab57;
  --grad-1-b:#ff6f97;
  --grad-2-a:#56b4ff;
  --grad-2-b:#4a73ff;
  --grad-3-a:#8a7cff;
  --grad-3-b:#c06cff;
  --grad-4-a:#47d39a;
  --grad-4-b:#8fd95b;
}
html[data-theme="ocean"]{ --text:#0f3968; --muted:#3f6898; }
html[data-theme="rose"]{ --text:#4d2145; --muted:#7d5573; }
html[data-theme="mint"]{ --text:#11463d; --muted:#446f67; }
