/* ===== P73 PIPELINE MODAL VISIBILITY HOTFIX ===== */
.pipeline-modal-backdrop {
  align-items: flex-start;
  justify-content: center;
  overflow: auto;
  padding: 10px 12px;
}
.pipeline-upgrade-modal {
  width: min(1680px, calc(100vw - 24px));
  max-width: calc(100vw - 24px);
  max-height: calc(100vh - 20px);
  overflow: auto;
  padding: 22px 22px 16px;
  border-radius: 28px;
  margin: 0 auto;
}
.pipeline-add-layout {
  display: grid;
  grid-template-columns: minmax(0, 2.35fr) minmax(260px, 0.72fr);
  gap: 16px;
  align-items: start;
}
.pipeline-main-form,
.pipeline-wa-panel {
  min-width: 0;
  padding: 16px;
}
.pipeline-wa-panel {
  width: 100%;
  max-width: 100%;
  overflow: hidden;
}
.pipeline-auto-grid {
  grid-template-columns: repeat(4, minmax(138px, 1fr));
  gap: 12px;
}
.pipeline-form-field {
  padding: 10px 10px 12px !important;
  border-radius: 16px !important;
}
.pipeline-form-field > span {
  margin: 0 auto 6px;
  padding: 4px 8px;
  min-height: 22px;
}
.pipeline-form-field input,
.pipeline-form-field select,
.pipeline-form-field textarea,
.pipeline-wa-panel input,
.pipeline-wa-panel select {
  min-height: 42px;
  padding: 10px 12px !important;
  font-size: 14px;
}
.pipeline-inline-picker-row {
  grid-template-columns: minmax(0, 1fr) 40px;
}
.pipeline-inline-add-btn {
  width: 40px;
  min-width: 40px;
  min-height: 40px !important;
  border-radius: 12px !important;
  font-size: 20px !important;
}
.pipeline-inline-field-row .ghost-btn {
  min-height: 38px;
  padding-inline: 10px;
}
.pipeline-file-box .helper-text {
  min-height: 30px;
  font-size: 11px;
  line-height: 1.35;
}
.pipeline-file-box input[type="file"] {
  margin-top: 4px;
  max-width: 100%;
  font-size: 11px;
}
.pipeline-message-preview {
  min-height: 156px;
  max-height: 220px;
  padding: 12px;
  font-size: 12px;
  line-height: 1.45;
}
.pipeline-attach-check {
  gap: 6px;
  font-size: 11px;
}
.extra-grid {
  grid-template-columns: repeat(4, minmax(120px, 1fr));
  gap: 10px;
}
.pipeline-notes-field textarea {
  min-height: 72px;
}
.pipeline-modal-footer {
  margin-top: 10px;
  padding-top: 8px;
}
@media (max-width: 1320px) {
  .pipeline-add-layout {
    grid-template-columns: minmax(0, 1.95fr) minmax(250px, 0.78fr);
    gap: 14px;
  }
  .pipeline-auto-grid {
    grid-template-columns: repeat(4, minmax(128px, 1fr));
    gap: 10px;
  }
}
@media (max-width: 1180px) {
  .pipeline-add-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .pipeline-wa-panel {
    grid-column: 1 / -1;
  }
  .pipeline-auto-grid,
  .extra-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 760px) {
  .pipeline-modal-backdrop {
    padding: 8px;
  }
  .pipeline-upgrade-modal {
    width: calc(100vw - 16px);
    max-width: calc(100vw - 16px);
    max-height: calc(100vh - 16px);
    padding: 14px 14px 12px;
    border-radius: 20px;
  }
  .pipeline-auto-grid,
  .extra-grid {
    grid-template-columns: 1fr;
  }
}
/* ===== END P73 PIPELINE MODAL VISIBILITY HOTFIX ===== */

