.teamsShell{font-family:"Plus Jakarta Sans","Segoe UI",Arial,sans-serif!important;position:relative}
.teamsShell *{box-sizing:border-box}
.teamsPanel,.teamsLeft,.chatMain,.rightPanel,.teamsChatHeader,.profileHero,.threadBtn,.personBtn,.sideItem,.mutedBox,.reviewCard,.composer,.teamsSearch,.chatInput,.composeBox textarea,.teamsTabs button,.teamsAction:not(.primary){background:#fff!important;background-image:none!important}
.teamsPanel{border-color:#d7e6f7!important;box-shadow:0 16px 36px rgba(41,77,122,.08)!important;overflow:hidden!important;position:relative!important}
.teamsPanel::before{content:""!important;display:block!important;position:absolute!important;inset:0 0 auto 0!important;height:3px!important;background:linear-gradient(90deg,#ff7a18,#ffad42,#47a3ff)!important;animation:cc434Glow 4.5s ease-in-out infinite!important}
.teamsPanel::after,.teamsLeft::before,.teamsLeft::after,.chatMain::before,.chatMain::after,.rightPanel::before,.rightPanel::after{display:none!important;content:none!important}
@keyframes cc434Glow{0%,100%{opacity:.72}50%{opacity:1;filter:saturate(1.12)}}
