/* CC26_434 central tracking reports runtime for prebuilt SPA. Light theme only. */
html body .cc434r{--ink:#173a67;--muted:#6b8199;--line:#d8e6f4;--orange:#ff7a18;--orange2:#ffad42;--sky:#2f80ed;display:grid;gap:15px;color:var(--ink);font-family:"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
html body .cc434r *{box-sizing:border-box}
html body .cc434r button,html body .cc434r input,html body .cc434r select{font:inherit}
.cc434r-hero{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:24px;padding:19px;background:linear-gradient(135deg,#fff 0%,#f4f9ff 62%,#fff6ea 100%);box-shadow:0 15px 36px rgba(31,73,125,.09)}
.cc434r-hero:before{content:"";position:absolute;inset:0 0 auto;height:4px;background:linear-gradient(90deg,#ff7a18,#ffad42,#2f80ed)}
.cc434r-title{font-size:26px;font-weight:1000;letter-spacing:-.035em;color:#12345e}.cc434r-sub{margin-top:5px;font-size:13px;font-weight:750;color:var(--muted)}
.cc434r-filter{display:flex;align-items:end;gap:8px;flex-wrap:wrap;margin-top:15px}.cc434r-filter label{display:grid;gap:5px;font-size:10.5px;font-weight:950;color:#607791;text-transform:uppercase;letter-spacing:.035em}
.cc434r-filter input,.cc434r-filter select{height:40px;border:1px solid #cfe0f2;border-radius:13px;background:#fff;padding:0 11px;color:#173a67;font-weight:850;outline:none;min-width:132px}
.cc434r-btn{height:40px;border-radius:13px;padding:0 13px;font-size:12px;font-weight:950;cursor:pointer;border:1px solid #d7e6f7;background:#fff;color:#173a67}.cc434r-btn.on{background:#fff0df;border-color:#ffc785;color:#bd5c12}.cc434r-btn.primary{border:0;background:linear-gradient(135deg,#ff7a18,#ffad42);color:#fff}.cc434r-btn.blue{background:#edf6ff;border-color:#cfe0f2;color:#1d619f}.cc434r-btn:disabled{opacity:.58;cursor:default}
.cc434r-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.cc434r-card{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:22px;background:#fff;padding:15px;box-shadow:0 11px 27px rgba(38,78,122,.07)}.cc434r-card:before{content:"";position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,#ff7a18,#ffad42)}.cc434r-card.blue:before{background:linear-gradient(90deg,#2f80ed,#6aafff)}.cc434r-card.green:before{background:linear-gradient(90deg,#1eaa78,#68d2aa)}.cc434r-card.red:before{background:linear-gradient(90deg,#ff7a18,#ef655b)}
.cc434r-cardhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px}.cc434r-cardhead strong{font-size:17px;font-weight:1000;letter-spacing:-.02em}.cc434r-chip{padding:6px 9px;border-radius:999px;background:#f4f9ff;color:#58728e;font-size:9.5px;font-weight:950}
.cc434r-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.cc434r-metric{min-height:89px;text-align:left;border:1px solid #dce9f6;border-radius:16px;background:linear-gradient(145deg,#fff,#f8fbff);padding:10px;cursor:pointer;color:#173a67;transition:transform .15s ease,box-shadow .15s ease}.cc434r-metric:hover[data-detail]{transform:translateY(-2px);box-shadow:0 9px 20px rgba(35,87,140,.1)}.cc434r-metric.warn{background:#fff8f1;border-color:#ffd9b6}.cc434r-metric span{display:block;font-size:10px;font-weight:950;color:#71859c;text-transform:uppercase;letter-spacing:.035em}.cc434r-metric strong{display:block;margin-top:6px;font-size:22px;font-weight:1000;letter-spacing:-.03em;color:#173a67}.cc434r-metric.warn strong{color:#c76011}.cc434r-metric small{display:block;margin-top:4px;font-size:10px;font-weight:800;color:#7890a8}
.cc434r-tablecard{border:1px solid var(--line);border-radius:22px;background:#fff;box-shadow:0 11px 27px rgba(38,78,122,.06);overflow:hidden}.cc434r-tablehead{display:flex;justify-content:space-between;align-items:center;padding:14px 15px;border-bottom:1px solid #e4eef8}.cc434r-tablehead strong{font-size:16px;font-weight:1000}.cc434r-tablewrap{overflow:auto;max-height:430px}.cc434r-table{width:100%;border-collapse:separate;border-spacing:0;min-width:980px}.cc434r-table th{position:sticky;top:0;z-index:1;background:#f5f9fe;color:#607892;font-size:9.5px;text-transform:uppercase;letter-spacing:.04em;text-align:left;padding:10px;border-bottom:1px solid #dce8f5}.cc434r-table td{padding:10px;border-bottom:1px solid #edf2f7;color:#173a67;font-size:11.5px;font-weight:780;vertical-align:top}.cc434r-rec{cursor:pointer}.cc434r-rec:hover td{background:#f8fbff}.cc434r-rec small{color:#71859b;font-weight:850}.cc434r-note,.cc434r-error{padding:11px 14px;border:1px solid #dce9f6;border-radius:15px;background:#f8fbff;color:#657e98;font-size:11.5px;font-weight:800}.cc434r-error{background:#fff6f3;border-color:#ffd3c8;color:#9f4334}
.cc434r-modalback{position:fixed;inset:0;z-index:100000;background:rgba(19,47,82,.34);backdrop-filter:blur(5px);display:grid;place-items:center;padding:18px}.cc434r-modal{width:min(1180px,96vw);max-height:88vh;display:flex;flex-direction:column;background:#fff;border:1px solid #d7e6f7;border-radius:24px;box-shadow:0 30px 80px rgba(22,54,92,.25);overflow:hidden}.cc434r-modalhead{display:flex;align-items:center;justify-content:space-between;padding:14px 17px;background:linear-gradient(135deg,#f7fbff,#fff8ef);border-bottom:1px solid #dce8f5}.cc434r-modalhead strong{font-size:17px;font-weight:1000}.cc434r-close{width:34px;height:34px;border-radius:11px;border:1px solid #d7e6f7;background:#fff;color:#4e6781;font-size:20px;font-weight:1000;cursor:pointer}.cc434r-modalbody{overflow:auto;min-height:180px}.cc434r-empty{padding:30px;text-align:center;color:#70859b;font-size:13px;font-weight:850}
/* replace old elapsed timer with active-work-only timer */
html body .cc408-work-timer-pill{display:none!important}
html body .cc434-active-work-pill{position:relative!important;display:flex!important;align-items:center!important;gap:9px!important;width:158px!important;min-width:158px!important;max-width:158px!important;height:46px!important;flex:0 0 158px!important;margin-left:8px!important;padding:6px 10px!important;border-radius:17px!important;background:linear-gradient(135deg,#f5fbff,#fff 56%,#fff5ea)!important;border:1px solid rgba(8,119,201,.22)!important;box-shadow:0 9px 22px rgba(8,119,201,.1)!important;overflow:hidden!important;color:#102b46!important}.cc434-active-work-pill:before{content:"";position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,#0877c9,#18a8e0 52%,#ff6b16,#ff9a34)}.cc434-active-dot{width:9px;height:9px;border-radius:50%;background:#20bf6b;box-shadow:0 0 0 4px rgba(32,191,107,.12);flex:0 0 9px}.cc434-active-work-pill.paused .cc434-active-dot{background:#ff8a21;box-shadow:0 0 0 4px rgba(255,138,33,.13)}.cc434-active-label{font-size:8px;line-height:1;font-weight:950;letter-spacing:.09em;text-transform:uppercase;color:#62788c;margin-bottom:3px}.cc434-active-value{width:82px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;font-size:16px;line-height:1;font-weight:950;color:#0d2e4c}.cc434-active-sub{font-size:8.5px;line-height:1;font-weight:850;color:#6f8193;margin-top:4px;white-space:nowrap}
