/* CC88 — Revenue filters and ranked analytics; responsive, client-side only. */
.cc88-filter-panel{padding:12px!important;margin:8px 0 10px!important;border:1px solid #d5e3f4!important;background:linear-gradient(110deg,#fff,#f6fbff)!important;border-radius:17px!important}
.cc88-filter-top,.cc88-date-filters,.cc88-advanced{display:grid;grid-template-columns:minmax(220px,2fr) repeat(2,minmax(150px,1fr)) repeat(3,auto);gap:8px;align-items:end}
.cc88-filter-top>label,.cc88-date-filters>label,.cc88-advanced>label,.cc88-rank-controls>label{display:flex;min-width:0;flex-direction:column;gap:4px;font-size:11px;font-weight:800;color:#3b5572}
.cc88-filter-top input,.cc88-filter-top select,.cc88-date-filters input,.cc88-date-filters select,.cc88-advanced select,.cc88-rank-controls select{width:100%;height:34px;border:1px solid #cbdaf0;border-radius:8px;padding:4px 8px;background:#fff;color:#203b55;font:inherit;font-size:12px;outline-offset:1px}
.cc88-date-filters{margin-top:9px;grid-template-columns:minmax(175px,1fr) repeat(2,minmax(145px,1fr)) minmax(250px,2fr)}
.cc88-date-quick{display:flex;gap:5px;flex-wrap:wrap}
.cc88-date-quick button{padding:8px 9px;border:1px solid #d1ddf1;background:#f5f9ff;border-radius:8px;cursor:pointer;color:#284267;font-weight:750;font-size:11px}
.cc88-advanced{margin-top:10px;grid-template-columns:repeat(4,minmax(130px,1fr));align-items:stretch}
.cc88-filter-meta{margin-top:9px;color:#335779;font-size:12px;font-weight:650}
.cc88-date-note{font-size:11px;color:#835622;margin-top:4px}
.cc88-filter-stats{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:8px;margin:8px 0}
.cc88-filter-stat{min-height:62px;padding:8px 12px;border:1px solid #d4e1f4;border-radius:11px;background:linear-gradient(140deg,#fff,#f2f7ff);display:flex;flex-direction:column;justify-content:center;gap:4px}
.cc88-filter-stat small{font-size:12px;color:#52708d;font-weight:800}.cc88-filter-stat strong{font-size:20px;color:#183553}
.cc88-analysis{padding:14px!important}.cc88-analysis-header{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.cc88-analysis-header h2{font-size:18px;margin:0}.cc88-analysis-header span{font-size:12px;color:#607591}
.cc88-top-cards{display:grid;grid-template-columns:repeat(5,minmax(135px,1fr));gap:8px;margin:12px 0}.cc88-top-card{display:flex;text-align:left;flex-direction:column;gap:6px;min-width:0;padding:12px;border:1px solid #d5e1f2;border-radius:12px;background:linear-gradient(140deg,#fefcff,#ecf5ff);cursor:pointer}.cc88-top-card small{font-weight:800;font-size:11px;color:#4f6784}.cc88-top-card strong{font-size:15px;color:#213c61;overflow-wrap:anywhere}.cc88-top-card span{font-size:12px;color:#366798}
.cc88-rank-controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:14px 0}.cc88-rank-controls label{min-width:170px}.cc88-rank-controls span{font-size:12px;color:#496783}
.cc88-leaderboard-list{max-height:430px;overflow:auto;border:1px solid #dce6f4;border-radius:11px}.cc88-rank-table{width:100%;min-width:700px;border-collapse:collapse;font-size:12px}.cc88-rank-table th{position:sticky;top:0;background:#e8effd;color:#244361;padding:10px;text-align:left;z-index:1}.cc88-rank-table td{padding:9px 10px;border-bottom:1px solid #e9f0fb}.cc88-rank-table tbody tr{cursor:pointer}.cc88-rank-table tbody tr:hover,.cc88-rank-active{background:#eef6ff!important}.cc88-rank-table td small{display:block;color:#72859e}
