/* CC860 - Admin Control profile safety tools (manual request, manager only). */
.cc860-profile-safety {padding:14px}
.cc860-safety-section {padding:14px 0;border-top:1px solid rgba(74,92,134,.16)}
.cc860-safety-section .table-title {margin-bottom:5px}
.cc860-safety-search {display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-top:12px}
.cc860-safety-search input {flex:1 1 260px;min-width:180px;width:auto;max-width:560px}
.cc860-safety-search button {min-height:38px}
.cc860-safety-result {margin-top:12px;padding:12px;border:1px solid rgba(74,92,134,.20);border-radius:12px;background:rgba(255,255,255,.82);overflow-wrap:anywhere}
