html body .cc936-chat-toast{position:fixed!important;left:50%!important;right:auto!important;transform:translateX(-50%)!important;width:min(380px,calc(100vw - 24px))!important;max-height:250px!important;background:linear-gradient(120deg,rgba(255,255,255,.97),rgba(232,242,255,.94))!important;border:1px solid #b9cdeb!important;border-radius:18px!important;box-shadow:0 12px 34px #1a356426!important;backdrop-filter:blur(12px);font-family:Inter,"Segoe UI",sans-serif!important;color:#142840!important;animation:cc159-chat-enter .2s ease-out both!important;padding:10px!important}
html body .cc936-chat-open{padding:0 26px 0 0!important;width:100%!important}.cc936-chat-copy{min-width:0!important}.cc936-chat-copy strong{color:#162d4a!important;font-size:14px!important;font-weight:800!important}.cc936-chat-body{color:#233b58!important;font-size:12px!important;line-height:1.4!important;max-height:52px!important;overflow:auto!important;white-space:pre-wrap!important}.cc936-chat-kicker{font-size:10px!important;color:#496789!important}.cc936-chat-progress{display:none!important}
.cc159-chat-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:6px}.cc159-chat-actions button,.cc159-chat-reply button{border:1px solid #bfd1ef;border-radius:8px;background:linear-gradient(110deg,#e9f2ff,#f4edff);color:#24426c;font:700 11px/1.3 Inter,"Segoe UI",sans-serif;padding:4px 9px;cursor:pointer}.cc159-chat-reply{display:grid;grid-template-columns:1fr auto;gap:6px;margin-top:8px}.cc159-chat-reply input{min-width:0;background:#fff;border:1px solid #9fbde7;border-radius:8px;padding:7px;font-size:12px;color:#172d4a}.cc159-chat-reply small{grid-column:1/-1;color:#ab2243;font-size:11px}
html body .cc159-reminder-nav{display:flex!important;align-items:center!important;gap:5px!important;margin-top:6px!important;color:#183859!important;font:700 11px/1.3 Inter,"Segoe UI",sans-serif!important}.cc159-reminder-nav button{border:1px solid #a9c5e7!important;border-radius:7px!important;background:linear-gradient(120deg,#fff,#e4f0ff)!important;color:#204877!important;min-height:25px!important;padding:2px 8px!important;font-weight:800!important;cursor:pointer}.cc159-reminder-position{flex:1;text-align:center}html body.cc159-inline-undo #cc126-popup-undo{display:none!important}
html body .cc730-direct-reminder-deck .cc388-title{font-family:Inter,"Segoe UI",sans-serif!important;font-size:15px!important;font-weight:800!important;line-height:1.3!important;color:#142c4c!important;text-shadow:none!important}html body .cc730-direct-reminder-deck .cc388-label{font-family:Inter,"Segoe UI",sans-serif!important;font-size:10px!important;font-weight:800!important;letter-spacing:.02em!important;line-height:1.3!important}html body .cc730-direct-reminder-deck .cc388-card{backdrop-filter:none!important;opacity:1!important;text-shadow:none!important}
html body .cc560-jump-btn{font-family:Inter,"Segoe UI",sans-serif!important;font-size:11px!important;font-weight:800!important;text-shadow:none!important;backdrop-filter:none!important;filter:none!important}
@keyframes cc159-chat-enter{from{opacity:0;translate:0 -8px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){html body .cc936-chat-toast{animation:none!important}}

@font-face{font-family:Inter;font-style:normal;font-weight:100 900;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}
